def ascii_art(p,x0,x1,y0,y1,dpi=400):
    pm=pymupdf.open(p)[0].get_pixmap(dpi=dpi,clip=pymupdf.Rect(x0,y0,x1,y1))
    a=np.frombuffer(pm.samples,dtype=np.uint8).reshape(pm.height,pm.width,3).astype(int)
    g=a.mean(2); H,W=g.shape; out=[]
    for r in range(0,H,3):
        line=''
        for c in range(0,W,2):
            b=g[r:r+3,c:c+2]
            line+='#' if (b<170).mean()>0.35 else ('+' if (b<205).mean()>0.2 else '.')
